// This file was generated by agent-compose 0.0.0-dev from `main.yml` (target `staging`).
//
// It is a build artifact, not source: `agent-compose build` overwrites it,
// and `agent-compose build --check` fails when it has been edited. The spec
// is the single source of truth (PRD 5.12); to own this code instead, copy
// the whole directory out and stop regenerating it.
// The OTLP/JSON span exporter: one settled trace envelope in, one
// `ExportTraceServiceRequest` out (PRD resolved q51, `docs/trace.md` §12).
//
// # Why this is hand-written
//
// Resolved q51 settles the SDK question against the dependency: "OTLP/JSON over
// HTTP is a stable spec the hub can emit directly, so the exporter is
// hand-written and held by a **conformance fixture corpus** rather than by a
// vendored SDK". That corpus is `tests/fixtures/otlp-conformance/`, run through
// this very module by `tests/toolchain/otlp-conformance.mjs` and driven from
// `tests/otlp_conformance.rs` — the discipline CLAUDE.md's validation strategy
// applies to CEL, applied to span output. So there is no OpenTelemetry package
// here and no `npm` dependency of any kind: the only import is a `node:` builtin
// for the hash the ids are derived with.
//
// # What it is not
//
// It is not a tracer. Nothing here instruments anything, holds a context, or
// samples: the input is a trace this project already recorded and settled, and
// the output is that record restated on a wire a collector speaks. A deployment
// that wants protobuf points an OTel Collector at this endpoint and lets it
// re-encode — which is the answer `docs/trace.md` §12.7 names for a
// protobuf-only vendor.
//
// # Determinism
//
// Every byte this module produces is a function of its two arguments. The ids
// are SHA-256 over stable strings rather than random bytes, the span order is
// the document's own walk order, and nothing reads the clock — which is what
// makes the conformance corpus able to pin exact output, and what lets two
// exports of one trace (an at-least-once delivery retried, a journal replayed)
// carry the same ids rather than two views of one execution.

import { createHash } from "node:crypto";

import type {
  DispatchRecord,
  HumanPause,
  ModelCall,
  StoreRecord,
  TraceDocument,
  TraceEntry,
} from "./runtime.ts";

// ---------------------------------------------------------------------------
// The wire shapes
// ---------------------------------------------------------------------------

/**
 * One OTLP attribute value.
 *
 * Proto3's JSON mapping is what fixes the spellings: an `int64` travels as a
 * **string**, a `double` as a number, and an array as `{ "arrayValue": {
 * "values": [ … ] } }`. A collector reading `intValue: 3` and one reading
 * `intValue: "3"` are both real, and the second is what the mapping says, so it
 * is what this writes.
 */
export type OtlpValue =
  | { readonly stringValue: string }
  | { readonly boolValue: boolean }
  | { readonly intValue: string }
  | { readonly arrayValue: { readonly values: readonly OtlpValue[] } };

/** One `key`/`value` pair, as every OTLP attribute list holds them. */
export interface OtlpAttribute {
  readonly key: string;
  readonly value: OtlpValue;
}

/** One span event: something that happened at an instant inside a span. */
export interface OtlpEvent {
  readonly timeUnixNano: string;
  readonly name: string;
  readonly attributes: readonly OtlpAttribute[];
}

/** One span link: a pointer at a span that is not this span's parent. */
export interface OtlpLink {
  readonly traceId: string;
  readonly spanId: string;
  readonly attributes: readonly OtlpAttribute[];
}

/**
 * A span's outcome.
 *
 * `code` is the enum `0` unset, `1` ok, `2` error. Written as a number rather
 * than as `"STATUS_CODE_ERROR"`: proto3's JSON mapping admits both spellings and
 * every receiver takes the number, which is what the OpenTelemetry JavaScript
 * exporter itself emits.
 */
export interface OtlpStatus {
  readonly code: 0 | 1 | 2;
  readonly message?: string;
}

/** One span. */
export interface OtlpSpan {
  readonly traceId: string;
  readonly spanId: string;
  /** Absent on a root span nothing outside this deployment started. */
  readonly parentSpanId?: string;
  readonly name: string;
  /** `1` internal, `3` client — see [`spans`] for which is which. */
  readonly kind: 1 | 3;
  readonly startTimeUnixNano: string;
  readonly endTimeUnixNano: string;
  readonly attributes: readonly OtlpAttribute[];
  readonly events: readonly OtlpEvent[];
  readonly links: readonly OtlpLink[];
  readonly status: OtlpStatus;
}

/** The instrumentation scope every span of one export shares. */
export interface OtlpScope {
  readonly name: string;
  readonly version: string;
}

/** What the whole POST body is (`ExportTraceServiceRequest`). */
export interface ExportTraceServiceRequest {
  readonly resourceSpans: readonly {
    readonly resource: { readonly attributes: readonly OtlpAttribute[] };
    readonly scopeSpans: readonly {
      readonly scope: OtlpScope;
      readonly spans: readonly OtlpSpan[];
    }[];
  }[];
}

// ---------------------------------------------------------------------------
// What the exporter is told besides the trace
// ---------------------------------------------------------------------------

/**
 * A W3C `traceparent`, parsed (PRD resolved q51's first amendment).
 *
 * The caller's trace, adopted rather than replaced: an embedded graph started by
 * a request that carried one exports **into** its caller's trace, which is the
 * whole of what makes the sink usable from inside somebody else's system.
 */
export interface TraceParent {
  /** 32 lowercase hex characters, never all zero. */
  readonly traceId: string;
  /** 16 lowercase hex characters, never all zero — the caller's own span. */
  readonly spanId: string;
  /** The two hex digits of `trace-flags`, carried as written. */
  readonly flags: string;
}

/**
 * Everything the export needs that the trace envelope does not carry.
 *
 * The envelope is the record of a run and nothing else (`docs/trace.md` §2), so
 * the deployment's identity, the execution's clock window and the caller's trace
 * arrive here instead — and the exporter stays a pure function of the two, which
 * is what the conformance corpus pins.
 */
export interface ExportContext {
  /** The deploy target this artifact was built for; `local` when none was named. */
  readonly target: string;
  /** `ARTIFACT_HASH` — the identity of the tree that produced the trace. */
  readonly artifact: string;
  /** `COMPILER_VERSION` — the agent-compose release that emitted this module. */
  readonly compiler: string;
  /** When the execution opened, as an ISO 8601 instant. */
  readonly startedAt: string;
  /** When it settled, as an ISO 8601 instant. */
  readonly endedAt: string;
  /** The inbound `traceparent` this execution was started by, where there was one. */
  readonly parent?: TraceParent;
}

// ---------------------------------------------------------------------------
// The entry point
// ---------------------------------------------------------------------------

/** The scope every span this module writes belongs to. */
const SCOPE_NAME = "agent-compose";

/**
 * Map one settled trace envelope to an OTLP/JSON `ExportTraceServiceRequest`.
 *
 * The tree it builds (`docs/trace.md` §12.1 is the normative table):
 *
 *  * the **execution** is the root span, named for the flow that ran;
 *  * every **entry**, at every depth, is a span under the span of whatever ran
 *    it — the root for a top-level entry, the enclosing entry's span for one
 *    under `inner`, the dispatch's span for one under a dispatch record;
 *  * every **dispatch record**, on either carrier, is a span under its entry;
 *  * every **model call** is a span under its entry, with its failovers, its
 *    refusal and its tool calls as events on it;
 *  * every **store record** and a `human` node's **pause** are events on the
 *    entry's own span;
 *  * a **flow-as-tool** call links the model-call span to the dispatch span that
 *    answered it (resolved q51's `span links`).
 *
 * What is deliberately **not** carried is payload: `StoreRecord.answer` and
 * `ToolCallRecord.result` are in the envelope and are not mapped to attributes.
 * `docs/trace.md` §11 keeps a model's completion and a tool's answer out of this
 * format, and the two fields that survive that rule survive it for a reader of
 * *this* deployment's own trace file — shipping them to a third-party collector
 * is a wider disclosure than the sink was asked for.
 */
export function exportRequest(
  document: TraceDocument,
  context: ExportContext,
): ExportTraceServiceRequest {
  const traceId = context.parent?.traceId ?? traceIdOf(document.execution_id);
  const window = {
    start: unixNano(context.startedAt, context.startedAt),
    end: unixNano(context.endedAt, context.startedAt),
  };
  const emitted: OtlpSpan[] = [];
  const state: Emission = { document, context, traceId, window, spans: emitted };

  const rootId = spanIdOf(document.execution_id, "execution", document.execution_id);
  emitted.push({
    traceId,
    spanId: rootId,
    ...(context.parent === undefined ? {} : { parentSpanId: context.parent.spanId }),
    name: document.flow,
    kind: 1,
    startTimeUnixNano: window.start,
    endTimeUnixNano: window.end,
    attributes: [
      text("agentcompose.execution.id", document.execution_id),
      text("agentcompose.flow", document.flow),
      text("agentcompose.status", document.status),
      integer("agentcompose.trace_version", document.trace_version),
      ...(document.error === undefined ? [] : [text("agentcompose.error", document.error)]),
    ],
    events: [],
    links: [],
    status:
      document.status === "completed"
        ? { code: 1 }
        : document.status === "failed"
          ? { code: 2, ...(document.error === undefined ? {} : { message: document.error }) }
          : // A run holding a question nobody answered is neither: it is the one
            // envelope status that is not an outcome, so it is left `UNSET` and
            // said in `agentcompose.status` instead (`docs/trace.md` §12.4).
            { code: 0 },
  });

  walk(state, document.entries, document.execution_id, rootId);

  return {
    resourceSpans: [
      {
        resource: { attributes: resourceAttributes(document, context) },
        scopeSpans: [
          {
            scope: { name: SCOPE_NAME, version: context.compiler },
            spans: emitted,
          },
        ],
      },
    ],
  };
}

/** What one export is accumulating, threaded through the walk. */
interface Emission {
  readonly document: TraceDocument;
  readonly context: ExportContext;
  readonly traceId: string;
  readonly window: { readonly start: string; readonly end: string };
  readonly spans: OtlpSpan[];
}

/**
 * The stable resource attributes of resolved q51's second amendment
 * (`docs/trace.md` §12.6).
 *
 * They are a promise rather than a convenience: the amendment holds the metrics
 * door open by requiring "stable resource attributes so a later, standalone
 * `@opentelemetry/sdk-metrics` adoption correlates on any collector without
 * touching the span exporter". A later exporter that resources itself the same
 * way joins these spans on any backend; one that resourced itself differently
 * would publish two services that happen to share a name.
 */
function resourceAttributes(
  document: TraceDocument,
  context: ExportContext,
): readonly OtlpAttribute[] {
  return [
    // The flow, because it is the identity every trace carries and the unit an
    // execution belongs to. A project serving four flows publishes four services
    // on a collector, which is the reading an operator watching one graph wants.
    text("service.name", document.flow),
    text("service.namespace", context.target),
    // The **artifact hash**, which is what a version means here: PRD 5.12 makes
    // the generated tree the deployable, and `docs/distributed.md` §4.1 makes its
    // hash the thing two processes agree on. A compiler version would name the
    // tool rather than the service, and it is below under `telemetry.sdk`.
    text("service.version", context.artifact),
    text("deployment.environment.name", context.target),
    text("telemetry.sdk.name", SCOPE_NAME),
    text("telemetry.sdk.language", "nodejs"),
    text("telemetry.sdk.version", context.compiler),
  ];
}

// ---------------------------------------------------------------------------
// The walk
// ---------------------------------------------------------------------------

/**
 * Emit one array of entries as spans under `parent`, and everything under them.
 *
 * `prefix` is the instance path the frames of these entries hang off (grammar
 * §9.4, `docs/trace.md` §8): the execution id at the root, an enclosing entry's
 * own path under `inner`, and a dispatch record's `idempotencyKey` under a
 * dispatched instance — which is the same path that record already carries, read
 * rather than derived a second time.
 */
function walk(
  state: Emission,
  entries: readonly TraceEntry[],
  prefix: string,
  parent: string,
): void {
  entries.forEach((entry, position) => {
    const path = `${prefix}/${entry.node}/${entry.traversal}`;
    // **The position is part of the key, and it has to be.** Two attempts of a
    // `flow:` node under `retry:` put two instances in one `inner` array, and
    // grammar §9.4 gives their frames the same path on purpose — a retried
    // effect reuses its key, which is what at-least-once means. Two spans of one
    // id would be one span to a collector, so the discriminator resolved q51
    // allows is the entry's index in the array that holds it.
    const key = `${path}#${position}`;
    const spanId = spanIdOf(state.document.execution_id, "entry", key);
    state.spans.push({
      traceId: state.traceId,
      spanId,
      parentSpanId: parent,
      name: entry.node,
      kind: 1,
      ...entryWindow(state, entry),
      attributes: entryAttributes(entry, path),
      events: entryEvents(state, entry),
      links: [],
      status:
        entry.outcome === "completed"
          ? { code: 1 }
          : entry.outcome === "failed"
            ? { code: 2, ...(entry.error === undefined ? {} : { message: entry.error }) }
            : // A node its `on_error:` skipped did not succeed and did not fail
              // the run; its `error` says what was absorbed, and it is on the
              // attributes.
              { code: 0 },
    });

    (entry.models ?? []).forEach((call, made) => {
      modelSpan(state, entry, call, made, key, spanId);
    });
    dispatchSpans(state, entry.dispatches ?? [], spanId, "map");
    dispatchSpans(state, entry.toolDispatches ?? [], spanId, "tool");
    walk(state, entry.inner ?? [], path, spanId);
  });
}

/** Emit one carrier's dispatch records, and the instances under them. */
function dispatchSpans(
  state: Emission,
  records: readonly DispatchRecord[],
  entrySpan: string,
  carrier: "map" | "tool",
): void {
  records.forEach((record, position) => {
    const spanId = dispatchSpanId(state, record, position);
    state.spans.push({
      traceId: state.traceId,
      spanId,
      parentSpanId: entrySpan,
      name: record.target,
      kind: 1,
      startTimeUnixNano: state.window.start,
      endTimeUnixNano: state.window.end,
      attributes: [
        text("agentcompose.instance_path", record.idempotencyKey),
        text("agentcompose.dispatch.carrier", carrier),
        integer("agentcompose.dispatch.index", record.index),
        text("agentcompose.dispatch.target", record.target),
        text("agentcompose.dispatch.outcome", record.outcome),
        integer("agentcompose.attempts", record.attempts),
        ...(record.route === undefined ? [] : [text("agentcompose.dispatch.route", record.route)]),
        ...(record.variant === undefined
          ? []
          : [text("agentcompose.dispatch.variant", record.variant)]),
        ...(record.error === undefined ? [] : [text("agentcompose.error", record.error)]),
      ],
      events: [],
      links: [],
      status:
        record.outcome === "completed"
          ? { code: 1 }
          : record.outcome === "failed"
            ? { code: 2, ...(record.error === undefined ? {} : { message: record.error }) }
            : // `skipped` is a policy dropping an item and `detached` is a
              // dispatch nothing ever observed: neither is an outcome to colour.
              { code: 0 },
    });
    walk(state, record.inner ?? [], record.idempotencyKey, spanId);
  });
}

/**
 * Emit one model call as a span under its entry, with its ladder as events.
 *
 * `kind: 3` — a **client** span, because this is the one thing a node does that
 * leaves the process for another service. Everything else this module emits is
 * work the compiled graph did itself.
 */
function modelSpan(
  state: Emission,
  entry: TraceEntry,
  call: ModelCall,
  index: number,
  entryKey: string,
  entrySpan: string,
): void {
  const spanId = spanIdOf(
    state.document.execution_id,
    "model",
    `${entryKey}/model/${index}`,
  );
  const events: OtlpEvent[] = [];
  for (const failover of call.failovers) {
    events.push({
      timeUnixNano: state.window.start,
      name: "failover",
      attributes: [
        text("agentcompose.model.member", failover.model),
        text("agentcompose.model.condition", failover.condition),
        text("agentcompose.model.detail", failover.detail),
      ],
    });
  }
  if (call.refused !== undefined) {
    events.push({
      timeUnixNano: state.window.start,
      name: "refusal",
      attributes: [
        text("agentcompose.model.member", call.refused.model),
        ...(call.refused.condition === undefined
          ? []
          : [text("agentcompose.model.condition", call.refused.condition)]),
        text("agentcompose.model.detail", call.refused.detail),
      ],
    });
  }
  const links: OtlpLink[] = [];
  for (const made of call.toolCalls ?? []) {
    events.push({
      timeUnixNano: state.window.start,
      name: "tool_call",
      attributes: [
        text("agentcompose.tool.name", made.name),
        ...(made.target === undefined ? [] : [text("agentcompose.tool.target", made.target)]),
        text("agentcompose.tool.outcome", made.outcome),
        ...(made.instance === undefined
          ? []
          : [text("agentcompose.instance_path", made.instance)]),
        ...(made.error === undefined ? [] : [text("agentcompose.error", made.error)]),
      ],
    });
    if (made.instance === undefined) continue;
    // The **join** resolved q51 asks for as a span link. It is resolved by
    // lookup rather than by deriving the dispatch's span id from the path,
    // because a span id carries the record's position too (see [`walk`]) and one
    // instance path can be filed twice: `docs/trace.md` §8's map-item retry
    // re-runs a tool loop and reuses its keys. The first record carrying the key
    // is the one the call filed, and a call whose record is not on this entry —
    // which no run produces — links to nothing rather than to a guess.
    const filed = entry.toolDispatches ?? [];
    const found = filed.findIndex((record) => record.idempotencyKey === made.instance);
    const record = filed[found];
    if (record === undefined) continue;
    links.push({
      traceId: state.traceId,
      spanId: dispatchSpanId(state, record, found),
      attributes: [text("agentcompose.instance_path", made.instance)],
    });
  }
  state.spans.push({
    traceId: state.traceId,
    spanId,
    parentSpanId: entrySpan,
    name: call.model,
    kind: 3,
    startTimeUnixNano: state.window.start,
    endTimeUnixNano: state.window.end,
    attributes: [
      text("agentcompose.model", call.model),
      ...(call.servedBy === undefined
        ? []
        : [text("agentcompose.model.served_by", call.servedBy)]),
      ...(call.fallback === undefined
        ? []
        : [integer("agentcompose.model.fallback", call.fallback)]),
      integer("agentcompose.model.failovers", call.failovers.length),
    ],
    events,
    links,
    // A call no member answered is the failure PRD 5.9 asks a reader to be able
    // to see; every other call reached a provider that answered it.
    status:
      call.refused === undefined
        ? { code: 1 }
        : { code: 2, message: `${call.refused.model}: ${call.refused.detail}` },
  });
}

/** One dispatch record's span id — its instance path, plus its position. */
function dispatchSpanId(state: Emission, record: DispatchRecord, position: number): string {
  return spanIdOf(
    state.document.execution_id,
    "dispatch",
    `${record.idempotencyKey}#${position}`,
  );
}

/** One entry's own attributes. */
function entryAttributes(entry: TraceEntry, path: string): readonly OtlpAttribute[] {
  return [
    text("agentcompose.instance_path", path),
    text("agentcompose.flow", entry.flow),
    text("agentcompose.node", entry.node),
    integer("agentcompose.step", entry.step),
    integer("agentcompose.traversal", entry.traversal),
    text("agentcompose.outcome", entry.outcome),
    integer("agentcompose.attempts", entry.attempts),
    ...(entry.writes === undefined
      ? []
      : [strings("agentcompose.writes", entry.writes)]),
    ...(entry.fallback === undefined ? [] : [text("agentcompose.fallback", entry.fallback)]),
    ...(entry.error === undefined ? [] : [text("agentcompose.error", entry.error)]),
    ...(entry.routing === undefined
      ? []
      : [
          // **The whole decision, as JSON, and its targets beside it.** An OTLP
          // attribute is a scalar or an array of scalars and a routing decision
          // is neither, so the lossless half travels as one JSON string — PRD
          // 5.3 makes routing decisions data, and dropping the guards would make
          // this the one surface that does not carry them — while the targets
          // repeat as an array, because "which way did it go" is the question a
          // collector is asked to filter on.
          text("agentcompose.routing", JSON.stringify(entry.routing)),
          strings("agentcompose.routing.targets", entry.routing.targets),
        ]),
  ];
}

/** One entry's events: its store ops, and a `human` node's wait. */
function entryEvents(state: Emission, entry: TraceEntry): readonly OtlpEvent[] {
  const events: OtlpEvent[] = [];
  for (const record of entry.stores ?? []) {
    events.push({
      timeUnixNano: state.window.start,
      name: "store",
      attributes: storeAttributes(record),
    });
  }
  const pause = entry.human;
  if (pause !== undefined) {
    events.push({
      timeUnixNano: unixNano(pause.pausedAt, state.window.start),
      name: "human.paused",
      attributes: [
        ...(pause.expiresAt === undefined
          ? []
          : [text("agentcompose.human.expires_at", pause.expiresAt)]),
      ],
    });
    if (pause.settledAt !== undefined) {
      events.push({
        timeUnixNano: unixNano(pause.settledAt, state.window.start),
        name: "human.settled",
        attributes: [
          ...(pause.settled === undefined
            ? []
            : [text("agentcompose.human.settled", pause.settled)]),
        ],
      });
    }
  }
  return events;
}

/** One store op's attributes. The answer it read is **not** among them. */
function storeAttributes(record: StoreRecord): readonly OtlpAttribute[] {
  return [
    text("agentcompose.store", record.store),
    text("agentcompose.store.op", record.op),
    text("agentcompose.store.effect", record.effect),
    text("agentcompose.store.via", record.via),
    text("agentcompose.store.scope", record.scope),
    ...(record.key === undefined ? [] : [text("agentcompose.store.key", record.key)]),
    ...(record.idempotencyKey === undefined
      ? []
      : [text("agentcompose.instance_path", record.idempotencyKey)]),
    ...(record.deduped === undefined
      ? []
      : [{ key: "agentcompose.store.deduped", value: { boolValue: record.deduped } }]),
  ];
}

/**
 * The window one entry's span covers.
 *
 * **This format records no per-node timing** (`docs/trace.md` §12.5): an entry
 * carries a superstep number and a traversal ordinal, not a clock. So a span
 * that is not the root covers its execution's whole window, and the tree is a
 * structure rather than a latency waterfall — stated in the document rather than
 * papered over with a fabricated duration, because a collector rendering
 * invented spans as measurements is worse than one rendering honest structure.
 *
 * The one exception is the timing this format really does record: a `human`
 * node's wait, whose `pausedAt` and `settledAt` are on the entry (§3.4).
 */
function entryWindow(
  state: Emission,
  entry: TraceEntry,
): { readonly startTimeUnixNano: string; readonly endTimeUnixNano: string } {
  const pause: HumanPause | undefined = entry.human;
  if (pause === undefined) {
    return { startTimeUnixNano: state.window.start, endTimeUnixNano: state.window.end };
  }
  const start = unixNano(pause.pausedAt, state.window.start);
  return {
    startTimeUnixNano: start,
    endTimeUnixNano:
      pause.settledAt === undefined ? state.window.end : unixNano(pause.settledAt, start),
  };
}

// ---------------------------------------------------------------------------
// Attributes, ids and instants
// ---------------------------------------------------------------------------

function text(key: string, value: string): OtlpAttribute {
  return { key, value: { stringValue: value } };
}

/** An `int64` attribute — a **string** on the wire, per proto3's JSON mapping. */
function integer(key: string, value: number): OtlpAttribute {
  return { key, value: { intValue: String(Math.trunc(value)) } };
}

function strings(key: string, values: readonly string[]): OtlpAttribute {
  return {
    key,
    value: { arrayValue: { values: values.map((held) => ({ stringValue: held })) } },
  };
}

/**
 * The trace id for one execution: 16 bytes, 32 lowercase hex.
 *
 * SHA-256 over the execution id under a fixed label, truncated — a real hash
 * rather than `Math.random` or a clock, because two exports of one trace have to
 * carry one id: a delivery retried after a restart is the same delivery
 * (`docs/durability.md` §3.7), and a receiver that saw two trace ids for one
 * execution would render two traces.
 *
 * The label is versioned so that a later change of derivation is a change of
 * label rather than a silent re-identification of every execution.
 */
export function traceIdOf(execution: string): string {
  return nonZero(digest(`agent-compose/trace/v1\n${execution}`, 16));
}

/**
 * One span id: 8 bytes, 16 lowercase hex, derived from the execution, the kind
 * of span and the key that identifies it within the execution.
 *
 * The kind is in the hash so that two spans whose keys happen to coincide — an
 * entry and a dispatch at one instance path — cannot collide.
 */
export function spanIdOf(execution: string, kind: string, key: string): string {
  return nonZero(digest(`agent-compose/span/v1\n${execution}\n${kind}\n${key}`, 8));
}

/** The first `bytes` bytes of SHA-256 over `input`, in lowercase hex. */
function digest(input: string, bytes: number): string {
  return createHash("sha256").update(input, "utf8").digest("hex").slice(0, bytes * 2);
}

/**
 * An id that is never all zero, which the W3C trace context forbids and a
 * collector refuses.
 *
 * Unreachable in practice — a SHA-256 prefix of zeroes — and cheap enough to
 * state anyway: the alternative is an export a receiver drops for a reason
 * nothing in this project would ever explain.
 */
function nonZero(hex: string): string {
  return /^0+$/.test(hex) ? `${hex.slice(0, -1)}1` : hex;
}

/**
 * One ISO 8601 instant as OTLP's `fixed64` nanoseconds, written as a string.
 *
 * A string because proto3's JSON mapping writes every 64-bit integer as one, and
 * `BigInt` because a millisecond count times a million is past `Number`'s exact
 * range in the year 2255 and past nobody's patience to debug.
 *
 * An instant this cannot read falls back to `fallback` rather than to `NaN`: the
 * envelope's instants are this runtime's own `toISOString()` and a bad one is
 * unreachable, but an unreadable clock must not become the string `"NaN"` in a
 * field a collector parses as a number.
 */
function unixNano(instant: string, fallback: string): string {
  const milliseconds = Date.parse(instant);
  if (Number.isNaN(milliseconds)) {
    const spare = Date.parse(fallback);
    return Number.isNaN(spare) ? "0" : String(BigInt(spare) * 1_000_000n);
  }
  return String(BigInt(milliseconds) * 1_000_000n);
}

// ---------------------------------------------------------------------------
// The inbound `traceparent`
// ---------------------------------------------------------------------------

/**
 * Read a W3C `traceparent` header, or answer `undefined` for one that is not
 * valid (PRD resolved q51).
 *
 * **An invalid header is ignored silently**, which is the W3C trace-context
 * behaviour and not a leniency invented here: a vendor that writes a malformed
 * header must not cost the execution anything, and a receiver of this export is
 * better served by a trace of its own than by no trace at all.
 *
 * Version `00` is the version this understands. A **later** version is accepted
 * for its first four fields, which is what the specification asks of a
 * forward-compatible parser — a future version may append fields and must not
 * break a parser that reads the ones it knows — while `ff` is reserved and
 * refused. Both ids must be hex and neither may be all zero.
 */
export function parseTraceparent(header: string | undefined): TraceParent | undefined {
  if (header === undefined) return undefined;
  const fields = header.trim().split("-");
  if (fields.length < 4) return undefined;
  const [version, traceId, spanId, flags] = fields as [string, string, string, string];
  if (!/^[0-9a-f]{2}$/.test(version) || version === "ff") return undefined;
  // Version `00` is exactly four fields; a later one may carry more, and a
  // trailing empty field is a header that ended in `-` rather than a field.
  if (version === "00" && fields.length !== 4) return undefined;
  if (!/^[0-9a-f]{32}$/.test(traceId) || /^0+$/.test(traceId)) return undefined;
  if (!/^[0-9a-f]{16}$/.test(spanId) || /^0+$/.test(spanId)) return undefined;
  if (!/^[0-9a-f]{2}$/.test(flags)) return undefined;
  return { traceId, spanId, flags };
}
